def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    remaining = 100 - n
    if remaining <= 1:
        return 'D'

    opp_def_total = 0
    for _, o in history:
        if o == 'D':
            opp_def_total += 1

    my_last, opp_last = history[-1]
    if n >= 2:
        my_prev, opp_prev = history[-2]
    else:
        my_prev, opp_prev = 'C', 'C'

    if n >= 2 and opp_last == 'D' and opp_prev == 'D':
        if my_last == 'C':
            if my_prev == 'C' and opp_prev == 'D':
                return 'D'
            else:
                return 'C'
        elif my_last == 'D':
            if my_prev == 'D':
                failed = False
                last_forgive = -1
                for i in range(1, n):
                    if history[i][0] == 'C' and history[i-1][0] == 'D' and history[i-1][1] == 'D':
                        last_forgive = i
                if last_forgive != -1 and last_forgive + 1 < n:
                    if history[last_forgive + 1][1] == 'D':
                        failed = True
                if failed:
                    return 'D'
                if opp_def_total * 5 > n * 3:
                    return 'D'
                return 'C'
            else:
                return 'D'
        else:
            return 'D'
    else:
        if opp_last == 'D':
            if opp_def_total * 2 >= n:
                return 'D'
            if my_last == 'D':
                if rng.random() < 0.7:
                    return 'D'
            return 'C'
        else:
            return 'C'
